from .egate_interface import EgateInterface
from .table_parser import TableParser, ThroughputException, EGATE_ARGUMENTS_DICT, EGATE_COMMAND_TYPE_DICT, EGATE_UE_SCOPE_DICT
import re


class EgateRetryException(Exception):
    pass


class ThroughputMeasurement(object):
    """
    Class sends data from/to UEs
    """

    def __init__(self):
        self.egate_interface = EgateInterface()
        self.table_parser = TableParser()

    def get_cell_bler(self, cell, direction, retry=0):
        """
        Gets cell thoughput
        :param cell:                cell number
        :param direction:           direction
        :param retry:               number of retry after incorrect read egate output
        :return:                    bler
        """
        direction = direction.upper()
        if direction == 'DL':
            return self._get_cell_bler_dl(cell, retry)
        elif direction == 'UL':
            return self._get_cell_bler_ul(cell, retry)

    def _get_cell_bler_dl(self, cell, retry=0):
        bler_stats = None
        layer = 'harq'
        direction = 'dl'
        raw_bler_string = self._get_cell_stats(cell, direction, layer, retry)
        bler_output = self.table_parser.parse_egate_table(raw_bler_string)
        for output in bler_output:
            if output['Parameter'] == 'Number of DCIs':
                bler_stats = output
        if not bler_stats:
            raise ThroughputException()
        retx = float(bler_stats['Re-Tx'])
        total = int(bler_stats['Total'])
        bler_stats = 0
        if total:
            bler_stats = retx / total * 100
        return bler_stats

    def _get_cell_bler_ul(self, cell, retry=0):
        bler_stats = None
        layer = 'harq'
        direction = 'ul'
        raw_bler_string = self._get_cell_stats(cell, direction, layer, retry)
        bler_output = self.table_parser.parse_egate_table(raw_bler_string)
        for output in bler_output:
            if output['Parameter'] == 'Number of UL grants for new data':
                total = int(output['Value'])
            if output['Parameter'] == 'Number of UL grants for adaptive Re-TX':
                retx = float(output['Value'])
        bler_stats = 0
        if total:
            bler_stats = retx / total * 100
        return bler_stats

    def get_ul_retx_for_cell(self, cell_id, retry=5):
        adapt_retx = 0
        non_adapt_retx = 0
        raw_adapt_retx_string = self._get_cell_stats(cell_id, 'ul', 'harq', retry)
        ul_harq_output = self.table_parser.parse_egate_table(raw_adapt_retx_string)
        for output in ul_harq_output:
            if output['Parameter'] == 'Number of UL grants for adaptive Re-TX':
                adapt_retx = int(output['Value'])
            if output['Parameter'] == 'Number of non-adaptive Re-TXs':
                non_adapt_retx = int(output['Value'])
        return adapt_retx, non_adapt_retx

    def get_bearers_throughput(self, ue_id, selection_type, direction, retry=0):
        """
        Gets UE throughput
        :param ue_id:               ue_id
        :param selection_type:      type of throughput statistic: current, minimum, average, maximum
        :param direction:           direction: ul or dl
        :param retry:               number of retry after incorrect read egate output
        :return:                    throughput
        """
        raw_throughput_string = self._get_ue_stats(ue_id, direction, 'rlc', None, retry)
        throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        return {
            stat['Bearer']: self._convert_throughput_to_mbps(stat[EGATE_ARGUMENTS_DICT[selection_type]], precision=4)
            for stat in throughput_stats
        }

    def get_bearer_throughput_for_data_layer(self, ue, bearer, direction, selection_type, retry=0):
        """
        Gets bearer thoughput
        :param bearer:              bearer id
        :param ue:                  egate ue id
        :param direction:           direction
        :param retry:               number of retry after incorrect read egate output
        :return:                    throughput
        """

        raw_throughput_string = self._get_bearer_stats(ue, bearer, direction, retry)
        throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        try:
            return self._get_bearer_data_rate(throughput_stats, selection_type)
        except KeyError:
            raise ThroughputException()

    def get_bearer_throughput_for_data_layer_with_additional_params(self, ue, pdu, bearer, direction, selection_type, retry=0, **kwargs):
        """
        Gets bearer thoughput based on egate command bearer_stats
        param pdu:                  pdu id
        :param bearer:              bearer id
        :param ue:                  egate ue id
        :param direction:           direction
        :param retry:               number of retry after incorrect read egate output
        :param kwargs: other arguments necessary for egate bearer_stats command,
        Be aware that function doesn't check if Your parameters are correct
        :return:                    throughput
        """

        raw_throughput_string = self._get_bearer_stats_with_additional_params(ue, pdu, bearer, direction, retry, **kwargs)
        throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        try:
            return self._get_bearer_data_rate(throughput_stats, selection_type)
        except KeyError:
            raise ThroughputException()

    def get_ue_throughput(self, ue_id, selection_type, direction, layer='physical', scells=None, retry=0, precision=2, cell_group=None):
        """
        Gets UE throughput
        :param ue_id:               ue_id
        :param selection_type:      selection_type
        :param direction:           direction
        :param layer:               layer
        :param scells:              scells
        :param retry:               number of retry after incorrect read egate output
        :return:                    throughput
        """
        if scells != 'all':
            raw_throughput_string = self._get_ue_stats(ue_id, direction, layer, scells, retry, cell_group)
            throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        else:
            raw_throughput_string = self._get_ue_stats(ue_id, direction, layer, 'all', retry)
            throughput_stats_all = self.table_parser.parse_egate_table(raw_throughput_string)
            throughput_stats = throughput_stats_all
        try:
            return self._sum_ue_throughput_from_scells(throughput_stats, selection_type, precision=precision)
        except KeyError as wrong_stats:
            raise ThroughputException("Unknown selection type: {}", wrong_stats)

    def get_cell_throughput(self, cell, selection_type, direction, layer='mac', retry=0):
        """
        Gets cell thoughput
        :param cell:                cell
        :param selection_type:      selection_type
        :param direction:           direction
        :param layer:               layer
        :param retry:               number of retry after incorrect read egate output
        :return:                    throughput
        """
        raw_throughput_string = self._get_cell_stats(cell, direction, layer, retry)
        throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        try:
            return self._sum_ue_throughput_from_scells(throughput_stats, selection_type)
        except KeyError:
            raise ThroughputException()

    def get_cell_throughput_for_data_layer(self, cell, direction, layer, enb_id, retry=0):
        """
        Gets cell thoughput
        :param cell:                cell
        :param direction:           direction
        :param layer:               layer
        :param retry:               number of retry after incorrect read egate output
        :param enb_id:              enb id
        :return:                    throughput
        """
        raw_throughput_string = self._get_cell_stats(cell, direction, layer, retry, enb_id)
        throughput_stats = self.table_parser.parse_egate_table(raw_throughput_string)
        try:
            return self._get_cell_data_rate(throughput_stats)
        except KeyError:
            raise ThroughputException()

    def _change_to_bits(self, throughput, unit):
        if unit.lower() == "bps":
            return throughput
        if unit.lower() == "kbps":
            return throughput * 1000
        if unit.lower() == "mbps":
            return throughput * 1000 * 1000
        else:
            raise Exception("Unknown throughput unit: {}".format(unit))

    def _sum_tput(self, arg1, arg2):
        tput_pattern = r"([0-9.]+)\s*([a-zA-Z]+)?"
        a_string = re.search(tput_pattern, arg1)
        a = float(a_string.group(1))
        a_unit = a_string.group(2)
        a_unit = "bps" if a_unit is None else a_unit
        a_bits = self._change_to_bits(a, a_unit)
        b_string = re.search(tput_pattern, arg2)
        b = float(b_string.group(1))
        b_unit = b_string.group(2)
        b_unit = "bps" if b_unit is None else b_unit
        b_bits = self._change_to_bits(b, b_unit)
        sum = a_bits + b_bits
        if a_unit.lower() == "mbps" or b_unit.lower() == "mbps":
            return "{} {}".format(str(float(sum) / (1000 * 1000)), "mbps")
        elif a_unit.lower() == "kbps" or b_unit.lower() == "kbps":
            return "{} {}".format(str(float(sum) / 1000), "kbps")
        else:
            return "{} {}".format(str(float(sum)), "bps")

    def _remove_aggregated_row_from_statistics(self, statistics, attribute):
        return [r for r in statistics if r[attribute] != 'Aggregated']

    def _sum_ue_throughput_from_scells(self, throughput_stats, statistic, precision=2):
        result = "0 kbps"
        if "SCell" in throughput_stats[0]:
            throughput_stats = self._remove_aggregated_row_from_statistics(throughput_stats, "SCell")
        elif "S-Cell" in throughput_stats[0]:
            throughput_stats = self._remove_aggregated_row_from_statistics(throughput_stats, "S-Cell")
        for row in throughput_stats:
            result = self._sum_tput(result, row[EGATE_ARGUMENTS_DICT[statistic]])
        return self._convert_throughput_to_mbps(result, precision=precision)

    def _get_cell_data_rate(self, throughput_stats):
        for row in throughput_stats:
            if row['Parameter'] == 'Average data rate':
                return int(int(row['Value']) / 1000000)

    def _get_bearer_data_rate(self, throughput_stats, selection_type):
        parameter_to_find = {"average": "Average data rate",
                             "maximum": "Maximum data rate",
                             "minimum": "Minimum data rate"}
        for row in throughput_stats:
            if row['Parameter'] == parameter_to_find[selection_type]:
                return float(float(row['Value']) / 1000000)

    def _convert_throughput_to_mbps(self, throughput, precision=2):
        if throughput == '0':
            return 0
        conversion = {
            "mbps": lambda value: float(value),
            "kbps": lambda value: float(value) / 1000,
            "bps": lambda value: float(value) / 1000000,
        }
        throughput_value, throughput_unit = throughput.split()
        return round(conversion[throughput_unit.lower()](throughput_value), precision)

    def _get_ue_stats(self, ue_id, direction, layer, scells, retry, cell_group=None):
        try:
            cmd = "ue_stats_nr id={} type={}".format(ue_id, EGATE_COMMAND_TYPE_DICT[direction, layer])
        except KeyError:
            raise ThroughputException("Wrong direction and/or layer name")
        if scells:
            cmd += " scell={}".format(EGATE_UE_SCOPE_DICT[scells] if scells in EGATE_UE_SCOPE_DICT else scells)
        if cell_group:
            cmd += " cell_group={}".format(cell_group)
        return self._send_cmd_with_retry(cmd, retry)

    def _get_cell_stats(self, cells, direction, layer, retry, enb_id=1):
        try:
            cmd = "cell_stats_nr enb={} id={}".format(enb_id, cells)
        except KeyError:
            raise ThroughputException("Wrong direction and/or layer name")
        return self._send_cmd_with_retry(cmd, retry)

    def _get_bearer_stats(self, ue, bearer, direction, retry):
        cmd = "bearer_stats id={} ue={} dir={}".format(bearer, ue, direction)
        return self._send_cmd_with_retry(cmd, retry)

    def _get_bearer_stats_with_additional_params(self, ue, pdu, bearer, direction, retry, **kwargs):
        if bearer:
            arguments = " ".join(["{}={}".format(key, value) for key, value in kwargs.items()])
            cmd = "bearer_stats id={} ue={} dir={} ".format(bearer, ue, direction) + arguments
            return self._send_cmd_with_retry(cmd, retry)
        else:
            arguments = " ".join(["{}={}".format(key, value) for key, value in kwargs.items()])
            cmd = "bearer_stats ue={} pdu={} {} dir={} ".format(ue, pdu, arguments, direction)
            return self._send_cmd_with_retry(cmd, retry)

    def _send_cmd_with_retry(self, cmd, retry):
        raw_throughput_string = ''
        for i in range(0, int(retry) + 1):
            raw_throughput_string = self.egate_interface.send_command_check_for_faults(cmd)
            if '===' in raw_throughput_string:
                break
            elif i == int(retry):
                raise EgateRetryException(
                    'Egate was not able to find valid throughput output in {} retries:\n {}'.format(
                        retry, raw_throughput_string
                    )
                )
        return raw_throughput_string
